import assert from 'node:assert/strict';import vm from 'node:vm';import {readFile,writeFile}from 'node:fs/promises';
const [mode,file,casesFile,expectedFile]=process.argv.slice(2),cases=JSON.parse(await readFile(casesFile,'utf8')),source=await readFile(file,'utf8'),snapshots=[];
for(const [name,expr]of cases){const context=vm.createContext({}),module=new vm.SourceTextModule(source,{context});await module.link(()=>{throw Error('unexpected dependency')});await module.evaluate();context.factory=module.namespace.instantiateMithrilNative;let value;try{value=vm.runInContext(expr,context)}catch(e){throw Error(name+': '+String(e))}snapshots.push([name,JSON.parse(JSON.stringify(value))]);}
if(mode==='record')await writeFile(expectedFile,JSON.stringify(snapshots,null,2)+'\n');else{assert.deepEqual(snapshots,JSON.parse(await readFile(expectedFile,'utf8')));assert.equal(snapshots.length,12);console.log('Native module init '+mode+':12 reference-derived runtime groups passed.');}
